contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(other != address(this));
        require(address(this).balance >= _am);

        uint otherBefore = c.balances(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint otherAfter = c.balances(other); if (__ESBMC_reverted()) return;

        assert(otherAfter == otherBefore);
    }

    receive() external payable {}
}

